// Manual sections grouped for the contents page (by title; a section not listed lands in the last group).
const GUIDE_GROUPS = [
  ['🌱', 'เริ่มต้น', ['เริ่มต้นใช้งาน', 'ใช้บน iPhone / iPad และแนวนอน', 'จัดหน้าแรกเอง', 'แบบทดสอบวัดระดับ']],
  ['📚', 'เรียนและฝึก', ['แฟลชการ์ดและ 4 ปุ่ม', 'ไถศัพท์ และเล่นด่วน', 'เล่นหลายรอบในวันเดียว', 'คำดื้อ และวิธีจำของฉัน', 'เกมทั้ง 32 แบบ', 'เรียนตามหมวด', 'เรียนตามเป้าหมาย', 'ศัพท์ตามสถานการณ์', 'ข้อผิดที่คนไทยพบบ่อย', 'บุพบทที่ตามหลังคำ', 'กริยาไม่ปกติ', 'อ่านเรื่องสั้น', 'รายการคำศัพท์', 'ปริศนาศัพท์ประจำวัน', 'ชุดของฉัน', 'ท้าดวลเพื่อน', 'แผนที่ด่าน', 'ค้นหาคำในตาราง']],
  ['🏆', 'ความก้าวหน้าและรางวัล', ['XP และเลเวล', 'สถิติและการคาดการณ์', 'สตรีค ภารกิจ และเหรียญ']],
  ['⚙️', 'ตั้งค่าและข้อมูล', ['ตั้งค่าทุกข้อ (สรุป)', 'เสียงอ่านและธีม', 'สำรองและกู้คืนข้อมูล', 'ซิงก์ข้อมูลอัตโนมัติ', 'อัปเดตแอป']],
  ['💡', 'ทริกและช่วยเหลือ', []],
];
function guideGroupOf(title) {
  const k = GUIDE_GROUPS.findIndex((g) => g[2].includes(title));
  return k < 0 ? GUIDE_GROUPS.length - 1 : k;
}
function renderGuide(from) {
  const back = from || 'home';
  const sec = (icon, title, body, open) => `<details class="card-box g-sec"${open ? ' open' : ''}>
      <summary><span class="g-ic" aria-hidden="true">${icon}</span><b>${title}</b></summary><div class="g-body">${body}</div></details>`;
  const groups = GUIDE_GROUPS.map(([ic, name], k) => {
    const items = GUIDE.filter((g) => guideGroupOf(g[1]) === k);
    return items.length ? `<section class="g-group"><h2 class="g-h"><span aria-hidden="true">${ic}</span>${name}<small>${items.length} หัวข้อ</small></h2>
      ${items.map(([icon, title, body]) => sec(icon, title, body, false)).join('')}</section>` : '';
  }).join('');
  view.innerHTML = `
    <div class="row" style="margin:4px 0 12px"><button class="btn ghost" id="gBack">‹ กลับ</button></div>
    <div class="g-hero"><div class="g-hero-ic" aria-hidden="true">📖</div><div><b>คู่มือการใช้งาน</b><div class="small muted">${GUIDE.length} หัวข้อ · แตะเพื่อเปิดอ่าน</div></div></div>
    <input class="g-search" id="gSearch" type="search" placeholder="🔍 ค้นหาในคู่มือ เช่น สตรีค, สำรอง, เกม" aria-label="ค้นหาในคู่มือ" autocomplete="off">
    <div class="guide" id="gList">${groups}</div>
    <div class="empty-box" id="gNone" hidden><div class="em">🔎</div><div>ไม่พบหัวข้อที่ตรงกัน<div class="small muted">ลองคำสั้นลง หรือคำอื่นที่ใกล้เคียง</div></div></div>
    <p class="center small muted">เวอร์ชัน ${APP_VERSION}</p>`;
  $('#gBack').onclick = () => go(back);
  const inp = $('#gSearch'), secs = [...view.querySelectorAll('.g-sec')], opened = secs.map((d) => d.open);
  inp.oninput = () => {
    const q = inp.value.trim().toLowerCase();
    let n = 0;
    secs.forEach((d, i) => {
      const hit = !q || d.textContent.toLowerCase().includes(q);
      d.hidden = !hit; if (hit) n++;
      d.open = q ? hit : opened[i];
    });
    view.querySelectorAll('.g-group').forEach((g) => { g.hidden = ![...g.querySelectorAll('.g-sec')].some((d) => !d.hidden); });
    $('#gNone').hidden = n > 0;
  };
}

let CHANGELOG = null;
function loadChangelog() {
  if (CHANGELOG) return Promise.resolve(CHANGELOG);
  return new Promise((res) => {
    const sc = document.createElement('script');
    sc.src = 'data/changelog.js?v=' + APP_VERSION;
    const done = () => { CHANGELOG = window.CHANGELOG || []; res(CHANGELOG); };
    sc.onload = done; sc.onerror = done;
    document.head.appendChild(sc);
  });
}
const verNum = (v) => String(v || '0').split('.').reduce((a, x) => a * 1000 + (+x || 0), 0);
const thaiDate = (d) => new Date(d + 'T12:00:00').toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: 'numeric' });
function renderChangelog(from) {
  const back = from || 'settings';
  view.innerHTML = `<div class="row" style="margin:4px 0 12px"><button class="btn ghost" id="clBack">‹ กลับ</button></div><div id="clBody" class="center muted" style="padding:24px">กำลังโหลด…</div>`;
  $('#clBack').onclick = () => go(back);
  loadChangelog().then((list) => {
    if (current !== 'changelog') return;
    const body = $('#clBody');
    body.className = '';
    body.removeAttribute('style');
    if (!list.length) list = [[APP_VERSION, 'โหลดประวัติไม่สำเร็จ ลองใหม่ตอนต่อเน็ตนะ', '']];
    const days = [];
    list.forEach((r) => {
      const k = r[2] || '';
      let g = days[days.length - 1];
      if (!g || g.d !== k) days.push(g = { d: k, rows: [] });
      g.rows.push(r);
    });
    let pick = 'all';
    const draw = () => {
      const shown = pick === 'all' ? days : days.filter((g) => g.d === pick);
      body.innerHTML = `<div class="cl-filter"><label for="clPick" class="small muted">แสดง</label>
        <select class="sel" id="clPick"><option value="all">ทั้งหมด (${list.length} อัปเดต · ${days.length} วัน)</option>${days.map((g) => `<option value="${esc(g.d)}"${g.d === pick ? ' selected' : ''}>${g.d ? thaiDate(g.d) : 'ไม่ระบุวัน'} (${g.rows.length})</option>`).join('')}</select></div>`
        + shown.map((g) => `<div class="cl-day"><span>${g.d ? thaiDate(g.d) : 'ไม่ระบุวัน'}</span><span class="cl-n">${g.rows.length} อัปเดต</span></div>`
          + g.rows.map(([v, t]) => `<div class="card-box cl-row${v === list[0][0] ? ' cl-new' : ''}"><div class="cl-v">${esc(v)}${v === APP_VERSION ? ' <span class="cl-tag">เวอร์ชันนี้</span>' : ''}</div><div class="cl-t">${esc(t)}</div></div>`).join('')).join('')
        + `<p class="center small muted">เวอร์ชัน ${APP_VERSION}</p>`;
      $('#clPick').onchange = (e) => { pick = e.target.value; draw(); };
    };
    draw();
  });
}
// After an update: once per version, offer a look at what changed (silent for brand-new installs).
function whatsNew() {
  if (S.seenVer === APP_VERSION) return;
  const first = S.seenVer == null && !Object.keys(S.prog).length;
  const older = S.seenVer == null || verNum(S.seenVer) < verNum(APP_VERSION);
  S.seenVer = APP_VERSION; save();
  if (first || !older || document.getElementById('updBar')) return;
  const b = document.createElement('div');
  b.id = 'newBar'; b.className = 'upd-bar'; b.setAttribute('role', 'status');
  b.innerHTML = `<span>🎉 อัปเดตเป็น ${APP_VERSION} แล้ว</span><button class="btn primary" data-new="go">ดูมีอะไรใหม่</button><button class="upd-x" data-new="x" aria-label="ปิด">✕</button>`;
  b.onclick = (e) => {
    const a = e.target.dataset.new;
    if (a === 'go') { b.remove(); go('changelog', current === 'changelog' ? 'settings' : current); }
    else if (a === 'x') b.remove();
  };
  document.body.appendChild(b);
}
